455	/** For strings. Short strings are stored in the object itself, and long strings are allocated separately.
456	  * NOTE It could also be suitable for arrays of numbers.
457	  */
458	struct SingleValueDataString //-V730
459	{
460	private:
461	    using Self = SingleValueDataString;
462	
463	    Int32 size = -1;    /// -1 indicates that there is no value.
464	    Int32 capacity = 0;    /// power of two or zero
465	    char * large_data;
466	
467	public:
468	    static constexpr Int32 AUTOMATIC_STORAGE_SIZE = 64;
469	    static constexpr Int32 MAX_SMALL_STRING_SIZE = AUTOMATIC_STORAGE_SIZE - sizeof(size) - sizeof(capacity) - sizeof(large_data);
470	
471	private:
472	    char small_data[MAX_SMALL_STRING_SIZE]; /// Including the terminating zero.
473	
474	public:
475	    static constexpr bool is_nullable = false;
476	    static constexpr bool is_any = false;
477	
478	    bool has() const
479	    {
480	        return size >= 0;
481	    }
482	
483	    const char * getData() const
484	    {
485	        return size <= MAX_SMALL_STRING_SIZE ? small_data : large_data;
486	    }
487	
488	    StringRef getStringRef() const
489	    {
490	        return StringRef(getData(), size);
491	    }
492	
493	    void insertResultInto(IColumn & to) const
494	    {
495	        if (has())
496	            assert_cast<ColumnString &>(to).insertDataWithTerminatingZero(getData(), size);
497	        else
498	            assert_cast<ColumnString &>(to).insertDefault();
499	    }
500	
501	    void write(WriteBuffer & buf, const ISerialization & /*serialization*/) const
502	    {
503	        writeBinary(size, buf);
504	        if (has())
505	            buf.write(getData(), size);
506	    }
