508	    void read(ReadBuffer & buf, const ISerialization & /*serialization*/, Arena * arena)
509	    {
510	        Int32 rhs_size;
511	        readBinary(rhs_size, buf);
512	
513	        if (rhs_size >= 0)
514	        {
515	            if (rhs_size <= MAX_SMALL_STRING_SIZE)
516	            {
517	                /// Don't free large_data here.
518	
519	                size = rhs_size;
520	
521	                if (size > 0)
522	                    buf.readStrict(small_data, size);
523	            }
524	            else
525	            {
526	                if (capacity < rhs_size)
527	                {
528	                    capacity = static_cast<Int32>(roundUpToPowerOfTwoOrZero(rhs_size));
529	                    /// It might happen if the size was too big and the rounded value does not fit a size_t
530	                    if (unlikely(capacity < rhs_size))
531	                        throw Exception(ErrorCodes::TOO_LARGE_STRING_SIZE, "String size is too big ({})", rhs_size);
532	
533	                    /// Don't free large_data here.
534	                    large_data = arena->alloc(capacity);
535	                }
536	
537	                size = rhs_size;
538	                buf.readStrict(large_data, size);
539	            }
540	        }
541	        else
542	        {
543	            /// Don't free large_data here.
544	            size = rhs_size;
545	        }
546	    }
