548	    /// Assuming to.has()
549	    void changeImpl(StringRef value, Arena * arena)
550	    {
551	        Int32 value_size = value.size;
552	
553	        if (value_size <= MAX_SMALL_STRING_SIZE)
554	        {
555	            /// Don't free large_data here.
556	            size = value_size;
557	
558	            if (size > 0)
559	                memcpy(small_data, value.data, size);
560	        }
561	        else
562	        {
563	            if (capacity < value_size)
564	            {
565	                /// Don't free large_data here.
566	                capacity = roundUpToPowerOfTwoOrZero(value_size);
567	                large_data = arena->alloc(capacity);
568	            }
569	
570	            size = value_size;
571	            memcpy(large_data, value.data, size);
