1061	/** Implement 'heavy hitters' algorithm.
1062	  * Selects most frequent value if its frequency is more than 50% in each thread of execution.
1063	  * Otherwise, selects some arbitrary value.
1064	  * http://www.cs.umd.edu/~samir/498/karp.pdf
1065	  */
1066	template <typename Data>
1067	struct AggregateFunctionAnyHeavyData : Data
1068	{
1069	    UInt64 counter = 0;
1070	
1071	    using Self = AggregateFunctionAnyHeavyData;
1072	
1073	    bool changeIfBetter(const IColumn & column, size_t row_num, Arena * arena)
1074	    {
1075	        if (this->isEqualTo(column, row_num))
1076	        {
1077	            ++counter;
1078	        }
1079	        else
1080	        {
1081	            if (counter == 0)
1082	            {
1083	                this->change(column, row_num, arena);
1084	                ++counter;
1085	                return true;
1086	            }
1087	            else
1088	                --counter;
1089	        }
1090	        return false;
1091	    }
1092	
1093	    bool changeIfBetter(const Self & to, Arena * arena)
1094	    {
1095	        if (this->isEqualTo(to))
1096	        {
1097	            counter += to.counter;
1098	        }
1099	        else
1100	        {
1101	            if ((!this->has() && to.has()) || counter < to.counter)
1102	            {
1103	                this->change(to, arena);
1104	                return true;
1105	            }
1106	            else
1107	                counter -= to.counter;
1108	        }
1109	        return false;
1110	    }
1111	
1112	    void addManyDefaults(const IColumn & column, size_t length, Arena * arena)
1113	    {
1114	        for (size_t i = 0; i < length; ++i)
1115	            changeIfBetter(column, 0, arena);
1116	    }
1117	
1118	    void write(WriteBuffer & buf, const ISerialization & serialization) const
1119	    {
1120	        Data::write(buf, serialization);
1121	        writeBinary(counter, buf);
1122	    }
1123	
1124	    void read(ReadBuffer & buf, const ISerialization & serialization, Arena * arena)
1125	    {
1126	        Data::read(buf, serialization, arena);
1127	        readBinary(counter, buf);
1128	    }
1129	
1130	    static const char * name() { return "anyHeavy"; }
1131	
1132	#if USE_EMBEDDED_COMPILER
1133	
1134	    static constexpr bool is_compilable = false;
1135	
1136	#endif
